    // -----------------------------------------------------------------------
    // #2056 — boot-time reconciliation. Task→goal status delivery is
    // fire-and-forget, so a crash between a task reaching a terminal state
    // and the ledger write landing leaves a permanently `running` row. The
    // sweep rides `TaskSupervisor::enable_persistence` — the same restore
    // that already reaps orphans — through the SHARED installer's
    // `on_restore` observer, so there is no new production call site and the
    // tests below drive `enable_persistence`, never the reconciler directly.
    // -----------------------------------------------------------------------

    // -----------------------------------------------------------------------
    // #14 (codex round 2) — parked-peer adoption through the restore observer.
    // -----------------------------------------------------------------------

    /// #14 (item A) — the COMPOSED per-turn wiring: one `on_restore` callback
    /// carrying BOTH the goal-task-row reconcile and the parked-peer
    /// adoption, exactly as the WS per-turn block now installs it. Drives the
    /// REAL path: a fresh supervisor over the shared ledger, the composed
    /// installer, then `enable_persistence` — the restore observer must
    /// adopt the parked peer row whose `result.md` is on the blackboard.
    #[test]
    fn ws_restore_composed_observer_adopts_parked_peer() {
        let dir = tempfile::TempDir::new().unwrap();
        let profile = "tenant-ws-restore";
        let wire = SessionKey::with_profile(profile, "api", "ws-restore-composed");
        let data_dir = dir.path().join("profile");
        let peers_root = data_dir.join("peers");
        let jsonl = dir.path().join("tasks.jsonl");

        // Staging turn (the pre-restart supervisor): register + bind the peer
        // task, persist the staged dir with brief + result + the task-id
        // binding — what the WS `emit_staged` callback now writes.
        let staging = octos_agent::TaskSupervisor::new();
        staging
            .enable_persistence(&jsonl)
            .expect("staging persistence");
        let task_id = crate::peers::bind_peer_supervised_task(
            &staging,
            crate::peers::peer_wire_key(profile, "ws-orphan"),
            &wire.to_string(),
        )
        .expect("bind peer");
        std::fs::create_dir_all(peers_root.join("ws-orphan")).unwrap();
        std::fs::write(peers_root.join("ws-orphan").join("brief.md"), "brief").unwrap();
        std::fs::write(peers_root.join("ws-orphan").join("result.md"), "findings").unwrap();
        std::fs::write(
            peers_root.join("ws-orphan").join("originator"),
            wire.to_string(),
        )
        .unwrap();
        assert!(crate::peers::persist_peer_task_id_binding(
            &peers_root,
            "ws-orphan",
            &task_id,
        ));
        drop(staging);

        // Next turn's fresh per-turn supervisor: restore parks the row, then
        // the COMPOSED restore observer adopts it.
        // Intermediate boot: the restart whose orphan sweep PARKS the peer
        // row. The in-process bind keeps the row's liveness lease ALIVE (the
        // sweep's live-worker exemption correctly does NOT park it — as the
        // peers-module #8 tests reproduce), so park it by hand; the JSONL
        // append is the durable part. Wired with the composed installer
        // (goal-only halves inert here: no goal) so the restore has ALREADY
        // been delivered when the NEXT boot replays — no stale undelivered
        // flag.
        let sweep_boot = octos_agent::TaskSupervisor::new();
        install_peer_restore_observers_composed(&sweep_boot, &data_dir, || None, |_restored| {});
        sweep_boot
            .enable_persistence(&jsonl)
            .expect("sweep boot restore");
        sweep_boot.mark_parked(&task_id, "orphaned across restart".to_string());
        drop(sweep_boot);

        // Next turn's fresh per-turn supervisor: restoring the SHARED ledger
        // fires the composed observer with the row Parked, and the adoption
        // half adopts it.
        let supervisor = octos_agent::TaskSupervisor::new();
        let adopt_supervisor = supervisor.clone();
        let adopt_profile = profile.to_owned();
        let adopt_master = wire.to_string();
        let adopt_data_dir = data_dir.clone();
        install_peer_restore_observers_composed(
            &supervisor,
            &data_dir,
            || None,
            move |_restored| {
                crate::peers::adopt_parked_peer_tasks_with_results(
                    &adopt_supervisor,
                    &adopt_profile,
                    &adopt_master,
                    &adopt_data_dir,
                    &adopt_supervisor.get_all_tasks(),
                );
            },
        );
        supervisor.enable_persistence(&jsonl).expect("restore");

        let row = supervisor.get_task(&task_id).expect("peer row");
        assert_eq!(
            row.status,
            octos_agent::TaskStatus::Completed,
            "the composed per-turn restore observer must adopt the parked peer \
             row whose result.md is already on the blackboard",
        );
        assert_eq!(
            row.output_files,
            vec![
                peers_root
                    .join("ws-orphan")
                    .join("result.md")
                    .display()
                    .to_string()
            ],
        );
    }

    /// #14 (item B) — a goal-bound parked peer with a result settles its goal
    /// ledger row through the COMPOSED gateway restore observer: adoption
    /// runs FIRST (re-stashing the restart-lost task→goal binding from the
    /// staged dir's `goal` file), reconcile sees the POST-adoption table, and
    /// the ledger row flips to `complete` instead of idling `running`.
    #[test]
    fn parked_peer_with_result_and_goal_row_settles() {
        let dir = tempfile::TempDir::new().unwrap();
        let profile = "tenant-peer-goal";
        let wire = SessionKey::with_profile(profile, "api", "peer-goal-settle");
        seed_goal(default_agent_orchestrator(), &wire, profile);
        let goal_id = default_agent_orchestrator()
            .goal_id_for_test(&wire)
            .expect("goal id");
        let jsonl = dir.path().join("tasks.jsonl");
        let peers_root = dir.path().join("peers");

        // ── boot 1 (staging turn) ─────────────────────────────────────────
        let staging = octos_agent::TaskSupervisor::new();
        wire_supervisor_for_goal_task_rows(&staging, &wire, profile, dir.path());
        staging
            .enable_persistence(&jsonl)
            .expect("staging persistence");
        let task_id = crate::peers::bind_peer_supervised_task(
            &staging,
            crate::peers::peer_wire_key(profile, "goal-orphan"),
            &wire.to_string(),
        )
        .expect("bind peer");
        std::fs::create_dir_all(peers_root.join("goal-orphan")).unwrap();
        std::fs::write(peers_root.join("goal-orphan").join("brief.md"), "brief").unwrap();
        std::fs::write(peers_root.join("goal-orphan").join("result.md"), "findings").unwrap();
        std::fs::write(
            peers_root.join("goal-orphan").join("originator"),
            wire.to_string(),
        )
        .unwrap();
        // `stage_peer`'s `goal` file: `goal_id\ntask_id` — the settle-binding
        // source for the adoption.
        std::fs::write(
            peers_root.join("goal-orphan").join("goal"),
            format!("{goal_id}\n{task_id}"),
        )
        .unwrap();
        assert!(crate::peers::persist_peer_task_id_binding(
            &peers_root,
            "goal-orphan",
            &task_id,
        ));

        // The crash window: the restart drops the in-memory settle binding;
        // the ledger row stays `running`.
        simulate_process_restart_losing_binding(&task_id);
        {
            let ledger = octos_fleet::GoalLedger::open(goal_task_ledger_path(dir.path(), &goal_id))
                .expect("ledger exists after registration");
            assert_eq!(
                ledger
                    .get_task(&task_id)
                    .expect("read row")
                    .expect("registration created a task row")
                    .status,
                "running",
                "precondition: the registration row is still running",
            );
        }
        drop(staging);

        // ── boot 2 (the restart whose orphan sweep PARKS the row) ─────────
        // The in-process bind keeps the row's liveness lease ALIVE (the
        // sweep's live-worker exemption correctly does NOT park it — as the
        // peers-module #8 tests reproduce), so park it by hand; the JSONL
        // append is the durable part. Wired with the REAL production gateway
        // installer so its restore is delivered NOW (adoption finds no
        // Parked row yet, no-op) — no stale undelivered flag for boot 3.
        let sweep_boot = octos_agent::TaskSupervisor::new();
        install_peer_restore_observers_resolving_at_callback(
            &sweep_boot,
            &wire,
            profile,
            dir.path(),
        );
        sweep_boot
            .enable_persistence(&jsonl)
            .expect("sweep boot restore");
        sweep_boot.mark_parked(&task_id, "orphaned across restart".to_string());
        drop(sweep_boot);

        // ── boot 3 (gateway restore shape, post-park) ─────────────────────
        let supervisor = octos_agent::TaskSupervisor::new();
        install_peer_restore_observers_resolving_at_callback(
            &supervisor,
            &wire,
            profile,
            dir.path(),
        );
        supervisor.set_on_terminal(move |event| {
            route_terminal_event_to_continuation_queue(event, None);
        });
        supervisor.enable_persistence(&jsonl).expect("restore");

        // Adoption ran: the parked row completed with the blackboard result…
        let row = supervisor.get_task(&task_id).expect("peer row");
        assert_eq!(row.status, octos_agent::TaskStatus::Completed);
        assert_eq!(
            row.output_files,
            vec![
                peers_root
                    .join("goal-orphan")
                    .join("result.md")
                    .display()
                    .to_string()
            ],
        );
        // …and the goal ledger row settled THROUGH the adoption: the binding
        // was re-stashed before `mark_completed`, so the change-feed settle
        // (synchronous in a non-tokio test) landed the terminal verdict.
        let ledger = octos_fleet::GoalLedger::open(goal_task_ledger_path(dir.path(), &goal_id))
            .expect("ledger");
        assert_eq!(
            ledger
                .get_task(&task_id)
                .expect("read row")
                .expect("row")
                .status,
            "complete",
            "the adoption's binding restore must settle the goal ledger row \
             (the #8 order left it `running` forever)",
        );
    }

    /// Drop a task's in-memory settle binding, reproducing exactly what a
    /// process restart does to it: the JSONL keeps whatever transitions were
    /// appended, the SQLite row keeps whatever landed, and the binding map is
    /// gone. Opens the crash window without stubbing any production path.
    fn simulate_process_restart_losing_binding(task_id: &str) {
        default_agent_orchestrator()
            .shared
            .goal_task_ledger_bindings
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .remove(task_id);
    }

    /// #2056 case 1 — a terminal supervisor row whose ledger write never
    /// landed is settled on the NEXT BOOT. Boot 1 registers the task through
    /// the real `on_register` observer (row created `running`), then loses
    /// the binding (restart) before the completion, so the change-feed settle
    /// finds nothing to route and the row stays `running`. Boot 2 is a fresh
    /// supervisor wired through the SAME production installer, whose
    /// `enable_persistence` rebuilds the terminal row from the JSONL — the
    /// reconcile sweep must settle it.
    #[test]
    fn should_settle_owed_ledger_row_when_supervisor_reboots_with_a_terminal_row() {
        let dir = tempfile::TempDir::new().unwrap();
        let profile = "tenant-taskrows-reconcile";
        let wire = SessionKey::with_profile(profile, "api", "goal-task-rows-reconcile");
        seed_goal(default_agent_orchestrator(), &wire, profile);
        let goal_id = default_agent_orchestrator()
            .goal_id_for_test(&wire)
            .expect("goal id");
        let jsonl = dir.path().join("tasks.jsonl");

        // ── boot 1 ──────────────────────────────────────────────────────
        let supervisor = octos_agent::TaskSupervisor::new();
        wire_supervisor_for_goal_task_rows(&supervisor, &wire, profile, dir.path());
        supervisor.enable_persistence(&jsonl).expect("persistence");
        let task_id = supervisor.register("web_probe", "call-2056-1", Some(&wire.to_string()));
        supervisor.mark_running(&task_id);
        simulate_process_restart_losing_binding(&task_id);
        supervisor.mark_completed(&task_id, vec![]);

        let ledger_path = goal_task_ledger_path(dir.path(), &goal_id);
        {
            let ledger = octos_fleet::GoalLedger::open(&ledger_path).expect("open ledger");
            let row = ledger.get_task(&task_id).expect("read row").expect("row");
            assert_eq!(
                row.status, "running",
                "precondition: the crash window left the row `running`"
            );
        }

        // ── boot 2 ──────────────────────────────────────────────────────
        let rebooted = octos_agent::TaskSupervisor::new();
        wire_supervisor_for_goal_task_rows(&rebooted, &wire, profile, dir.path());
        rebooted.enable_persistence(&jsonl).expect("persistence");

        let ledger = octos_fleet::GoalLedger::open(&ledger_path).expect("open ledger");
        let row = ledger.get_task(&task_id).expect("read row").expect("row");
        assert_eq!(
            row.status, "complete",
            "the boot reconcile settles the row the crash window stranded"
        );
        assert_eq!(
            ledger.task_authority(&task_id).expect("authority"),
            Some(octos_fleet::TaskSettleAuthority::Completion.rank()),
            "the reconcile persists the SAME authority rank the live path would"
        );
    }

    /// #2056 — the same repair, but ON A TOKIO RUNTIME, which is what serve
    /// and the gateway actually restore under. The offload chain is genuinely
    /// different there: the sweep's own ledger read runs in a `spawn_blocking`
    /// and the settle it re-drives offloads AGAIN from inside that blocking
    /// thread. If the nested offload did not schedule, production would repair
    /// nothing at all while every inline-mode test stayed green.
    #[tokio::test]
    async fn should_settle_owed_ledger_row_when_rebooting_under_a_tokio_runtime() {
        let dir = tempfile::TempDir::new().unwrap();
        let profile = "tenant-taskrows-reconcile-async";
        let wire = SessionKey::with_profile(profile, "api", "goal-task-rows-reconcile-async");
        seed_goal(default_agent_orchestrator(), &wire, profile);
        let goal_id = default_agent_orchestrator()
            .goal_id_for_test(&wire)
            .expect("goal id");
        let jsonl = dir.path().join("tasks.jsonl");
        let ledger_path = goal_task_ledger_path(dir.path(), &goal_id);

        let supervisor = octos_agent::TaskSupervisor::new();
        wire_supervisor_for_goal_task_rows(&supervisor, &wire, profile, dir.path());
        supervisor.enable_persistence(&jsonl).expect("persistence");
        let task_id = supervisor.register("web_probe", "call-2056-async", Some(&wire.to_string()));
        supervisor.mark_running(&task_id);
        await_ledger_task_status(&ledger_path, &task_id, "running").await;
        simulate_process_restart_losing_binding(&task_id);
        supervisor.mark_completed(&task_id, vec![]);

        let rebooted = octos_agent::TaskSupervisor::new();
        wire_supervisor_for_goal_task_rows(&rebooted, &wire, profile, dir.path());
        rebooted.enable_persistence(&jsonl).expect("persistence");

        await_ledger_task_status(&ledger_path, &task_id, "complete").await;
    }

    /// Poll a goal ledger until `task_id` reaches `status`, or fail after ~5s.
    /// Under a tokio runtime every ledger write is offloaded, so the effect of
    /// a production observer is asynchronous.
    async fn await_ledger_task_status(ledger_path: &std::path::Path, task_id: &str, status: &str) {
        for _ in 0..250 {
            if ledger_path.exists()
                && let Ok(ledger) = octos_fleet::GoalLedger::open(ledger_path)
                && let Ok(Some(row)) = ledger.get_task(task_id)
                && row.status == status
            {
                return;
            }
            tokio::time::sleep(std::time::Duration::from_millis(20)).await;
        }
        panic!("timed out waiting for task {task_id} to reach {status:?}");
    }

    /// #2056 case 2 — the reverse divergence, and the reason the sweep is
    /// LEDGER-first: the completion settled, but the JSONL append that would
    /// have recorded it never landed, so the rebuilt table shows a
    /// non-terminal row that the orphan sweep reaps as
    /// `Failed("orphaned across restart")` — final-failure authority (2),
    /// strictly greater than the completion (1) already in the ledger. A
    /// supervisor-first sweep would flip a `complete` row to `failed`;
    /// enumerating only rows with NO verdict (`authority < 0`) means the
    /// reconcile never even looks at it.
    #[test]
    fn should_not_regress_a_settled_row_when_the_rebuilt_supervisor_row_outranks_it() {
        let dir = tempfile::TempDir::new().unwrap();
        let profile = "tenant-taskrows-noregress";
        let wire = SessionKey::with_profile(profile, "api", "goal-task-rows-noregress");
        seed_goal(default_agent_orchestrator(), &wire, profile);
        let goal_id = default_agent_orchestrator()
            .goal_id_for_test(&wire)
            .expect("goal id");
        let jsonl = dir.path().join("tasks.jsonl");
        let stale_jsonl = dir.path().join("tasks-stale.jsonl");

        let supervisor = octos_agent::TaskSupervisor::new();
        wire_supervisor_for_goal_task_rows(&supervisor, &wire, profile, dir.path());
        supervisor.enable_persistence(&jsonl).expect("persistence");
        let task_id = supervisor.register("web_probe", "call-2056-2", Some(&wire.to_string()));
        supervisor.mark_running(&task_id);
        // Snapshot the durable JSONL *before* the completion: this is exactly
        // the on-disk state a lost terminal append leaves behind.
        std::fs::copy(&jsonl, &stale_jsonl).expect("snapshot the pre-completion ledger");
        supervisor.mark_completed(&task_id, vec![]);

        let ledger_path = goal_task_ledger_path(dir.path(), &goal_id);
        let (settled_at, settled_authority) = {
            let ledger = octos_fleet::GoalLedger::open(&ledger_path).expect("open ledger");
            let row = ledger.get_task(&task_id).expect("read row").expect("row");
            assert_eq!(
                row.status, "complete",
                "precondition: the completion landed"
            );
            (
                row.updated_at_ms,
                ledger.task_authority(&task_id).expect("authority"),
            )
        };

        // Reboot from the STALE jsonl: the row rebuilds non-terminal, and the
        // orphan sweep marks it `Failed` — owner-final authority.
        let rebooted = octos_agent::TaskSupervisor::new();
        wire_supervisor_for_goal_task_rows(&rebooted, &wire, profile, dir.path());
        rebooted
            .enable_persistence(&stale_jsonl)
            .expect("persistence");
        assert_eq!(
            rebooted.get_task(&task_id).expect("task").status,
            octos_agent::TaskStatus::Failed,
            "precondition: the orphan sweep reaped the stale row as failed",
        );

        let ledger = octos_fleet::GoalLedger::open(&ledger_path).expect("open ledger");
        let row = ledger.get_task(&task_id).expect("read row").expect("row");
        assert_eq!(
            row.status, "complete",
            "a higher-authority reconcile write must never regress the settled row"
        );
        assert_eq!(
            ledger.task_authority(&task_id).expect("authority"),
            settled_authority,
            "the persisted rank is untouched"
        );
        assert_eq!(
            row.updated_at_ms, settled_at,
            "the row was not rewritten at all"
        );
    }

    /// #2056 case 3 — idempotency: a boot after a CLEAN shutdown (every
    /// terminal already settled) performs NO ledger writes. Proven three
    /// ways — SQLite's `data_version` on an independent connection held open
    /// across the reboot is unchanged (it moves only when a DIFFERENT
    /// connection commits), the shared settle core records no new attempt for
    /// this task, and the row is field-equal.
    #[test]
    fn should_write_nothing_when_rebooting_after_a_clean_shutdown() {
        let dir = tempfile::TempDir::new().unwrap();
        let profile = "tenant-taskrows-clean";
        let wire = SessionKey::with_profile(profile, "api", "goal-task-rows-clean");
        seed_goal(default_agent_orchestrator(), &wire, profile);
        let goal_id = default_agent_orchestrator()
            .goal_id_for_test(&wire)
            .expect("goal id");
        let jsonl = dir.path().join("tasks.jsonl");

        let supervisor = octos_agent::TaskSupervisor::new();
        wire_supervisor_for_goal_task_rows(&supervisor, &wire, profile, dir.path());
        supervisor.enable_persistence(&jsonl).expect("persistence");
        let task_id = supervisor.register("web_probe", "call-2056-3", Some(&wire.to_string()));
        supervisor.mark_running(&task_id);
        supervisor.mark_completed(&task_id, vec![]);

        let ledger_path = goal_task_ledger_path(dir.path(), &goal_id);
        let probe = octos_fleet::GoalLedger::open(&ledger_path).expect("open ledger");
        let row_before = probe.get_task(&task_id).expect("read row").expect("row");
        assert_eq!(
            row_before.status, "complete",
            "precondition: clean shutdown"
        );
        let version_before = probe.data_version().expect("data_version");
        let attempts_before = goal_task_settle_attempts_for(&task_id);

        let rebooted = octos_agent::TaskSupervisor::new();
        wire_supervisor_for_goal_task_rows(&rebooted, &wire, profile, dir.path());
        rebooted.enable_persistence(&jsonl).expect("persistence");

        assert_eq!(
            probe.data_version().expect("data_version"),
            version_before,
            "a clean-shutdown boot must commit NOTHING to the ledger"
        );
        assert_eq!(
            goal_task_settle_attempts_for(&task_id),
            attempts_before,
            "the shared settle core is not entered at all"
        );
        let row_after = probe.get_task(&task_id).expect("read row").expect("row");
        assert_eq!(row_after.status, row_before.status);
        assert_eq!(row_after.updated_at_ms, row_before.updated_at_ms);
    }

    /// #2056 case 4 — the sweep DEFERS to a live incarnation. A restore does
    /// not only happen at process boot: the WS turn path builds a fresh
    /// supervisor and re-restores the shared per-session task ledger every
    /// turn, so the sweep can run while a settle chain for one of those tasks
    /// is queued or backing off. Re-stashing that task's binding would assign
    /// a new generation and kill the chain at its next staleness fence, so an
    /// owed row whose binding is still present is left to its owner.
    ///
    /// The scenario is built by replacing the settle listener with a no-op
    /// under its own stable key — the terminal fires, the delivery never
    /// happens, and (unlike case 1) the binding SURVIVES, which is exactly the
    /// in-flight shape.
    #[test]
    fn should_leave_the_binding_alone_when_a_live_incarnation_still_owns_the_task() {
        let dir = tempfile::TempDir::new().unwrap();
        let profile = "tenant-taskrows-inflight";
        let wire = SessionKey::with_profile(profile, "api", "goal-task-rows-inflight");
        seed_goal(default_agent_orchestrator(), &wire, profile);
        let goal_id = default_agent_orchestrator()
            .goal_id_for_test(&wire)
            .expect("goal id");
        let jsonl = dir.path().join("tasks.jsonl");

        let supervisor = octos_agent::TaskSupervisor::new();
        wire_supervisor_for_goal_task_rows(&supervisor, &wire, profile, dir.path());
        supervisor.enable_persistence(&jsonl).expect("persistence");
        let task_id = supervisor.register("web_probe", "call-2056-4", Some(&wire.to_string()));
        supervisor.mark_running(&task_id);
        // The terminal fires but its delivery never happens — the binding
        // stays, as it would for a chain still in a backoff gap.
        supervisor.set_on_change_listener(GOAL_TASK_ROW_SETTLE_LISTENER_KEY, |_| {});
        supervisor.mark_completed(&task_id, vec![]);
        let generation = default_agent_orchestrator()
            .goal_task_binding_generation_for_test(&task_id)
            .expect("the binding survives an undelivered terminal");

        let rebooted = octos_agent::TaskSupervisor::new();
        wire_supervisor_for_goal_task_rows(&rebooted, &wire, profile, dir.path());
        rebooted.enable_persistence(&jsonl).expect("persistence");

        assert_eq!(
            default_agent_orchestrator().goal_task_binding_generation_for_test(&task_id),
            Some(generation),
            "the sweep must not re-stash a binding a live chain is fenced against"
        );
        let ledger = octos_fleet::GoalLedger::open(goal_task_ledger_path(dir.path(), &goal_id))
            .expect("open ledger");
        let row = ledger.get_task(&task_id).expect("read row").expect("row");
        assert_eq!(
            row.status, "running",
            "the owed row is left to its owner, not settled behind its back"
        );
    }

    /// #2056 round 2 (H1) — a row that already carries the LOWEST verdict is
    /// still owed a correction. An observer classifies a mid-run signal as
    /// fatal, so the ledger settles `failed` at provisional rank 0 and KEEPS
    /// the binding as a correction window. The owner then watches the worker
    /// finish and calls `mark_completed`, which appends `Completed` to the
    /// JSONL BEFORE notifying the change feed (`task_supervisor.rs`,
    /// `persist_snapshot` then `notify_change`) — so a crash in that gap
    /// leaves the durable supervisor state saying completed and the ledger
    /// saying `failed`/0, with the correction lost.
    ///
    /// This is the exact stranded delivery this feature exists to repair, and
    /// it is the reason the sweep cannot exclude every existing verdict: rank
    /// 0 is legitimately displaceable (`sqlite_ledger.rs` pins completion over
    /// a provisional verdict), while ranks 1 and 2 are not.
    #[test]
    fn should_settle_a_provisional_row_when_the_restored_verdict_is_a_completion() {
        let dir = tempfile::TempDir::new().unwrap();
        let profile = "tenant-taskrows-provisional";
        let wire = SessionKey::with_profile(profile, "api", "goal-task-rows-provisional");
        seed_goal(default_agent_orchestrator(), &wire, profile);
        let goal_id = default_agent_orchestrator()
            .goal_id_for_test(&wire)
            .expect("goal id");
        let jsonl = dir.path().join("tasks.jsonl");
        let ledger_path = goal_task_ledger_path(dir.path(), &goal_id);

        let supervisor = octos_agent::TaskSupervisor::new();
        wire_supervisor_for_goal_task_rows(&supervisor, &wire, profile, dir.path());
        supervisor.enable_persistence(&jsonl).expect("persistence");
        let task_id = supervisor.register("web_probe", "call-2056-prov", Some(&wire.to_string()));
        supervisor.mark_running(&task_id);
        supervisor.mark_failed_observed(&task_id, "harness classified a mid-run error".to_owned());

        {
            let ledger = octos_fleet::GoalLedger::open(&ledger_path).expect("open ledger");
            assert_eq!(
                ledger.task_authority(&task_id).expect("authority"),
                Some(octos_fleet::TaskSettleAuthority::ProvisionalFailure.rank()),
                "precondition: the observer verdict landed at provisional rank",
            );
            assert!(
                default_agent_orchestrator().goal_task_binding_exists_for_test(&task_id),
                "precondition: a provisional failure retains its correction window",
            );
        }

        // The owner's correction is appended to the JSONL and then lost with
        // the process before the ledger notification is delivered.
        simulate_process_restart_losing_binding(&task_id);
        supervisor.mark_completed(&task_id, vec![]);
        {
            let ledger = octos_fleet::GoalLedger::open(&ledger_path).expect("open ledger");
            let row = ledger.get_task(&task_id).expect("read row").expect("row");
            assert_eq!(
                row.status, "failed",
                "precondition: the correction never reached the ledger",
            );
        }

        let rebooted = octos_agent::TaskSupervisor::new();
        wire_supervisor_for_goal_task_rows(&rebooted, &wire, profile, dir.path());
        rebooted.enable_persistence(&jsonl).expect("persistence");

        let ledger = octos_fleet::GoalLedger::open(&ledger_path).expect("open ledger");
        let row = ledger.get_task(&task_id).expect("read row").expect("row");
        assert_eq!(
            row.status, "complete",
            "the boot reconcile must repair a lost provisional→completion correction"
        );
        assert_eq!(
            ledger.task_authority(&task_id).expect("authority"),
            Some(octos_fleet::TaskSettleAuthority::Completion.rank()),
        );
    }

    /// #2056 round 2 (H2a) — the sweep must survive a restore that happens
    /// BEFORE the observers are wired. The cached session supervisor is
    /// enabled by whichever request touches it first, and some of those sites
    /// install only their own listener; a later wiring re-enables the SAME
    /// path, which returns at `enable_persistence`'s idempotence guard, so a
    /// restore-driven sweep would never fire for that supervisor again.
    /// Installing the restore observer therefore delivers a restore that has
    /// already happened and was not observed.
    #[test]
    fn should_reconcile_when_the_restore_happened_before_the_observers_were_wired() {
        let dir = tempfile::TempDir::new().unwrap();
        let profile = "tenant-taskrows-late-wire";
        let wire = SessionKey::with_profile(profile, "api", "goal-task-rows-late-wire");
        seed_goal(default_agent_orchestrator(), &wire, profile);
        let goal_id = default_agent_orchestrator()
            .goal_id_for_test(&wire)
            .expect("goal id");
        let jsonl = dir.path().join("tasks.jsonl");
        let ledger_path = goal_task_ledger_path(dir.path(), &goal_id);

        let supervisor = octos_agent::TaskSupervisor::new();
        wire_supervisor_for_goal_task_rows(&supervisor, &wire, profile, dir.path());
        supervisor.enable_persistence(&jsonl).expect("persistence");
        let task_id = supervisor.register("web_probe", "call-2056-late", Some(&wire.to_string()));
        supervisor.mark_running(&task_id);
        simulate_process_restart_losing_binding(&task_id);
        supervisor.mark_completed(&task_id, vec![]);

        // Reboot in the hostile order: restore first, wire second.
        let rebooted = octos_agent::TaskSupervisor::new();
        rebooted.enable_persistence(&jsonl).expect("persistence");
        wire_supervisor_for_goal_task_rows(&rebooted, &wire, profile, dir.path());

        let ledger = octos_fleet::GoalLedger::open(&ledger_path).expect("open ledger");
        let row = ledger.get_task(&task_id).expect("read row").expect("row");
        assert_eq!(
            row.status, "complete",
            "wiring the observers after the restore must still deliver the sweep"
        );

        // Round 3 (R5) — the "delivery is not repeated" half of this used to
        // compare `goal_task_settle_attempts_for` across a re-wire, which is
        // VACUOUS: that counter only moves once a candidate reaches the settle
        // core, and by this point the row is `complete` at rank 1, so a
        // duplicate delivery finds no candidate and the assertion holds either
        // way. Exactly-once is pinned where it can actually be observed —
        // at the observer itself, in `task_supervisor_tests.rs`
        // (`should_deliver_a_restore_exactly_once_however_the_wiring_is_ordered`
        // and `should_not_lose_a_restore_when_wiring_races_the_missed_restore_mark`).
        // What this test owns is the EFFECT: wiring after the restore repairs
        // the row at all.
    }

    /// #2056 round 2 (H2b) — restore goal resolution must NOT inherit the
    /// registration path's active-only filter. `active_goal_id` rejects every
    /// paused / blocked / budget-limited / complete goal, and `budget_limited`
    /// is a normal state a goal sits in for the rest of its life. Registration
    /// is right to refuse it (no new work is being recorded); reconciliation
    /// is not — the rows are already there and still wrong.
    #[test]
    fn should_reconcile_when_the_bound_goal_is_not_active() {
        let dir = tempfile::TempDir::new().unwrap();
        let profile = "tenant-taskrows-nonactive";
        let wire = SessionKey::with_profile(profile, "api", "goal-task-rows-nonactive");
        let orchestrator = default_agent_orchestrator();
        seed_goal(orchestrator, &wire, profile);
        let goal_id = orchestrator.goal_id_for_test(&wire).expect("goal id");
        let jsonl = dir.path().join("tasks.jsonl");
        let ledger_path = goal_task_ledger_path(dir.path(), &goal_id);

        let supervisor = octos_agent::TaskSupervisor::new();
        wire_supervisor_for_goal_task_rows(&supervisor, &wire, profile, dir.path());
        supervisor.enable_persistence(&jsonl).expect("persistence");
        let task_id = supervisor.register("web_probe", "call-2056-budget", Some(&wire.to_string()));
        supervisor.mark_running(&task_id);
        simulate_process_restart_losing_binding(&task_id);
        supervisor.mark_completed(&task_id, vec![]);

        // The goal exhausts its budget and freezes there — same goal id.
        orchestrator
            .set_goal(GoalSetRequest {
                session_id: wire.clone(),
                profile_id: profile.to_owned(),
                objective: "ship the thing".to_owned(),
                status: Some("budget_limited".to_owned()),
                token_budget: Some(1_000_000),
                transition_actor: None,
            })
            .expect("freeze the goal at budget_limited");
        assert_eq!(
            orchestrator.goal_status_for_test(&wire).as_deref(),
            Some("budget_limited"),
            "precondition: the goal is no longer active",
        );
        assert_eq!(
            orchestrator.goal_id_for_test(&wire).as_deref(),
            Some(goal_id.as_str()),
            "precondition: the status change kept the same goal id",
        );
        assert!(
            orchestrator.active_goal_id(&wire, profile).is_none(),
            "precondition: the registration resolver refuses a non-active goal",
        );

        let rebooted = octos_agent::TaskSupervisor::new();
        wire_supervisor_for_goal_task_rows(&rebooted, &wire, profile, dir.path());
        rebooted.enable_persistence(&jsonl).expect("persistence");

        let ledger = octos_fleet::GoalLedger::open(&ledger_path).expect("open ledger");
        let row = ledger.get_task(&task_id).expect("read row").expect("row");
        assert_eq!(
            row.status, "complete",
            "a budget-limited goal's stranded rows must still be reconciled"
        );
    }

    /// Peer-fleet auto-synthesis — the synthesis continuation dedupes PER-MASTER:
    /// a second enqueue for the same master collapses to the one queued turn,
    /// even with a different (larger) owned-slug set or peer count. There is no
    /// re-arm — one synthesis per fleet.
    #[test]
    fn peer_fleet_synthesis_continuation_dedupes_per_master() {
        let orchestrator = default_agent_orchestrator();
        let master = SessionKey::with_profile("tenant-fleet-synth", "api", "master-dedupe");
        let profile = "tenant-fleet-synth";

        let first = orchestrator.enqueue_peer_fleet_synthesis_continuation(
            &master,
            profile,
            &["alpha".to_owned(), "beta".to_owned()],
            2,
        );
        assert!(first.queued().is_some(), "first synthesis must queue");

        // A later evaluation — MORE peers, different slug set — must NOT stack a
        // second synthesis: the per-master key collapses onto the first.
        let dup = orchestrator.enqueue_peer_fleet_synthesis_continuation(
            &master,
            profile,
            &["alpha".to_owned(), "beta".to_owned(), "gamma".to_owned()],
            3,
        );
        assert!(
            dup.is_duplicate(),
            "a per-master key: a second synthesis for the same master must dedupe"
        );
        assert_eq!(
            orchestrator.pending_continuation_count_for_session_for_test(&master, profile),
            1,
            "a fleet synthesizes exactly once — never two queued continuations",
        );
    }

    /// Bug 1 (reset edge) — after a fleet RESET clears the recent-claim guard, a
    /// FRESH fleet completing within `RECENT_CLAIM_GUARD_WINDOW` still fires: its
    /// per-master enqueue is no longer collapsed against the just-claimed prior
    /// synthesis. Without the reset's `clear_peer_fleet_synthesis_claim`, the
    /// stable key would stay guarded and the fresh continuation would be dropped
    /// (marked-but-unsynthesized).
    #[test]
    fn fresh_fleet_after_reset_fires_within_claim_window() {
        let orchestrator = default_agent_orchestrator();
        let master = SessionKey::with_profile("tenant-fleet-reset", "api", "master-reset");
        let profile = "tenant-fleet-reset";
        let slugs = vec!["alpha".to_owned()];

        // Fleet A fires and is DRAINED (claimed) → recorded in the recent-claim
        // guard for the stable per-master key.
        assert!(
            orchestrator
                .enqueue_peer_fleet_synthesis_continuation(&master, profile, &slugs, 1)
                .queued()
                .is_some()
        );
        let drained = orchestrator.drain_ready_continuations_for_session(
            &master,
            profile,
            MasterContinuationRuntimeState::idle(),
            4,
        );
        assert!(
            drained.iter().any(
                |c| matches!(&c.reason, MasterContinuationReason::External(k)
                if k == PEER_FLEET_SYNTHESIS_EXTERNAL_KIND)
            ),
            "the first synthesis must drain (recording the claim)",
        );

        // WITHOUT a reset, a re-enqueue within the window is deduped by the guard
        // (the item already left `pending_by_key` when drained).
        assert!(
            orchestrator
                .enqueue_peer_fleet_synthesis_continuation(&master, profile, &slugs, 1)
                .is_duplicate(),
            "the recent-claim guard still holds the just-claimed key",
        );

        // RESET clears the guard entry for this master's key.
        orchestrator.clear_peer_fleet_synthesis_claim(&master);

        // A fresh fleet within the SAME window now fires — not suppressed.
        assert!(
            orchestrator
                .enqueue_peer_fleet_synthesis_continuation(&master, profile, &slugs, 1)
                .queued()
                .is_some(),
            "a fresh fleet after reset must fire, not be dropped by the stale guard",
        );
    }

    /// Peer-fleet auto-synthesis — the master continuation renders the
    /// gather-and-consolidate directive scoped to THIS master's OWNED slugs
    /// (codex #4), so the autonomous turn reads only its own fleet.
    #[test]
    fn peer_fleet_synthesis_prompt_directs_fleet_scoped_gather() {
        let orchestrator = default_agent_orchestrator();
        let master = SessionKey::with_profile("tenant-fleet-prompt", "api", "master-prompt");
        let profile = "tenant-fleet-prompt";
        let slugs = vec!["edison".to_owned(), "tesla".to_owned()];
        orchestrator.enqueue_peer_fleet_synthesis_continuation(&master, profile, &slugs, 2);
        let drained = orchestrator.drain_ready_continuations_for_session(
            &master,
            profile,
            MasterContinuationRuntimeState::idle(),
            4,
        );
        let synthesis = drained
            .iter()
            .find(|c| {
                matches!(&c.reason, MasterContinuationReason::External(kind)
                    if kind == PEER_FLEET_SYNTHESIS_EXTERNAL_KIND)
            })
            .expect("synthesis continuation must drain when the master is idle");
        let prompt = master_continuation_prompt(synthesis);
        assert!(
            prompt.contains("peer_gather"),
            "prompt must direct peer_gather: {prompt}"
        );
        assert!(
            prompt.contains("completed their work"),
            "prompt must state the fleet completed: {prompt}"
        );
        // Fleet-scoped: the OWNED slugs are named as the gather filter.
        assert!(
            prompt.contains("edison,tesla"),
            "prompt must scope peer_gather to the owned slugs: {prompt}"
        );
        assert!(
            prompt.contains("slugs` filter"),
            "prompt must instruct the slugs filter: {prompt}"
        );
    }

    /// Peer awaiting-input WAKE — a peer parking enqueues ONE autonomous
    /// continuation on the ORIGINATOR (master), carrying the peer slug + kind,
    /// and it drains when the master is idle.
    #[test]
    fn peer_awaiting_input_wake_enqueues_on_originator() {
        let orchestrator = default_agent_orchestrator();
        let master = SessionKey::with_profile("tenant-wake-enq", "api", "master-wake");
        let profile = "tenant-wake-enq";

        let outcome = orchestrator.enqueue_peer_awaiting_input_continuation(
            &master,
            profile,
            "edison",
            "approval-id-1",
            "approval",
            "shell: rm build cache",
        );
        assert!(
            outcome.queued().is_some(),
            "a peer park must enqueue a wake on the originator",
        );
        assert_eq!(
            orchestrator.pending_continuation_count_for_session_for_test(&master, profile),
            1,
            "exactly one wake queued for the master",
        );

        let drained = orchestrator.drain_ready_continuations_for_session(
            &master,
            profile,
            MasterContinuationRuntimeState::idle(),
            4,
        );
        let wake = drained
            .iter()
            .find(|c| {
                matches!(&c.reason, MasterContinuationReason::External(kind)
                    if kind == PEER_AWAITING_INPUT_EXTERNAL_KIND)
            })
            .expect("the wake must drain when the master is idle");
        assert_eq!(
            wake.metadata
                .get(PEER_AWAITING_INPUT_META_SLUG)
                .map(String::as_str),
            Some("edison"),
            "the wake carries the parked peer's slug",
        );
        assert_eq!(
            wake.metadata
                .get(PEER_AWAITING_INPUT_META_KIND)
                .map(String::as_str),
            Some("approval"),
            "the wake carries the park kind",
        );
    }

    /// Peer awaiting-input WAKE — two DISTINCT parks (distinct pending ids)
    /// enqueue TWO wakes: the per-pending-id key never collapses distinct
    /// blocks, so each is surfaced to the master at least once.
    #[test]
    fn peer_awaiting_input_two_distinct_parks_enqueue_two_wakes() {
        let orchestrator = default_agent_orchestrator();
        let master = SessionKey::with_profile("tenant-wake-two", "api", "master-two");
        let profile = "tenant-wake-two";

        assert!(
            orchestrator
                .enqueue_peer_awaiting_input_continuation(
                    &master,
                    profile,
                    "edison",
                    "pending-A",
                    "approval",
                    "one",
                )
                .queued()
                .is_some(),
            "first park queues",
        );
        assert!(
            orchestrator
                .enqueue_peer_awaiting_input_continuation(
                    &master,
                    profile,
                    "tesla",
                    "pending-B",
                    "question",
                    "two",
                )
                .queued()
                .is_some(),
            "a DISTINCT park (different pending id) queues a SECOND wake",
        );
        assert_eq!(
            orchestrator.pending_continuation_count_for_session_for_test(&master, profile),
            2,
            "two distinct parks → two wakes",
        );
    }

    /// Peer awaiting-input WAKE — a RETRY of the same park (same pending id)
    /// dedupes onto the already-queued wake: no continuation spam.
    #[test]
    fn peer_awaiting_input_same_park_retried_dedupes() {
        let orchestrator = default_agent_orchestrator();
        let master = SessionKey::with_profile("tenant-wake-dup", "api", "master-dup");
        let profile = "tenant-wake-dup";

        assert!(
            orchestrator
                .enqueue_peer_awaiting_input_continuation(
                    &master,
                    profile,
                    "edison",
                    "pending-same",
                    "approval",
                    "first",
                )
                .queued()
                .is_some(),
            "first enqueue of a park queues",
        );
        assert!(
            orchestrator
                .enqueue_peer_awaiting_input_continuation(
                    &master,
                    profile,
                    "edison",
                    "pending-same",
                    "approval",
                    "retry",
                )
                .is_duplicate(),
            "the SAME park (same pending id) dedupes — even with a different summary",
        );
        assert_eq!(
            orchestrator.pending_continuation_count_for_session_for_test(&master, profile),
            1,
            "a retried park never stacks a second wake",
        );
    }

    /// Peer awaiting-input WAKE — the rendered master turn names the parked peer
    /// slug + kind and directs the master at `peer_list` / `peer_respond`.
    #[test]
    fn peer_awaiting_input_prompt_names_slug_and_directs_peer_list() {
        let orchestrator = default_agent_orchestrator();
        let master = SessionKey::with_profile("tenant-wake-prompt", "api", "master-wprompt");
        let profile = "tenant-wake-prompt";
        orchestrator.enqueue_peer_awaiting_input_continuation(
            &master,
            profile,
            "edison",
            "approval-id-9",
            "question",
            "Which datastore should I migrate to?",
        );
        let drained = orchestrator.drain_ready_continuations_for_session(
            &master,
            profile,
            MasterContinuationRuntimeState::idle(),
            4,
        );
        let wake = drained
            .iter()
            .find(|c| {
                matches!(&c.reason, MasterContinuationReason::External(kind)
                    if kind == PEER_AWAITING_INPUT_EXTERNAL_KIND)
            })
            .expect("wake continuation must drain when the master is idle");
        let prompt = master_continuation_prompt(wake);
        assert!(
            prompt.contains("edison"),
            "prompt must name the parked peer's slug: {prompt}"
        );
        assert!(
            prompt.contains("question"),
            "prompt must state the park kind: {prompt}"
        );
        assert!(
            prompt.contains("peer_list"),
            "prompt must direct the master to peer_list: {prompt}"
        );
        assert!(
            prompt.contains("peer_respond"),
            "prompt must direct the master to peer_respond: {prompt}"
        );
    }

    /// codex #1 — a peer with a QUEUED (not-yet-run) `peer_send_input` follow-up
    /// is reported as having pending input, per (profile, slug); an unrelated
    /// slug / profile is not.
    #[test]
    fn has_pending_peer_send_input_detects_queued_follow_up() {
        let orchestrator = default_agent_orchestrator();
        let profile = "tenant-fleet-queued";
        let peer_wire = SessionKey::with_profile_topic(profile, "api", "peer-wire", "peer-worker");
        assert!(
            !orchestrator.has_pending_peer_send_input_for_peer(profile, "worker"),
            "no queued input before any injection",
        );
        let outcome = orchestrator.enqueue_peer_send_input_continuation(
            &peer_wire,
            profile,
            "worker",
            "occ-1",
            "follow up please",
        );
        assert_eq!(outcome, PeerSendInputEnqueueOutcome::Queued);
        assert!(
            orchestrator.has_pending_peer_send_input_for_peer(profile, "worker"),
            "a queued peer_send_input must be detected for its slug",
        );
        assert!(
            !orchestrator.has_pending_peer_send_input_for_peer(profile, "other-worker"),
            "a different slug must not report pending input",
        );
        assert!(
            !orchestrator.has_pending_peer_send_input_for_peer("tenant-other", "worker"),
            "a different profile must not report pending input",
        );
    }

    /// codex #1 (residual TOCTOU) — `peer_has_inflight_send_input` blocks the
    /// fleet-synthesis gate for BOTH a queued injection AND one that was just
    /// CLAIMED (popped by the drain, turn not yet active). Draining the queued
    /// item removes it from `pending_by_key` yet records it in
    /// `recently_claimed_external`, so a peer whose injection is mid-dispatch is
    /// never seen as settled — closing the premature/re-armed double synthesis.
    #[test]
    fn peer_has_inflight_send_input_covers_queued_and_just_claimed() {
        let orchestrator = default_agent_orchestrator();
        let profile = "tenant-fleet-claim";
        let peer_wire =
            SessionKey::with_profile_topic(profile, "api", "peer-wire-claim", "peer-worker");

        // Nothing yet.
        assert!(!orchestrator.peer_has_inflight_send_input(profile, "worker", Some(&peer_wire)));

        // Queued injection → the pending case blocks.
        let outcome = orchestrator.enqueue_peer_send_input_continuation(
            &peer_wire,
            profile,
            "worker",
            "occ-claim",
            "hi",
        );
        assert_eq!(outcome, PeerSendInputEnqueueOutcome::Queued);
        assert!(orchestrator.peer_has_inflight_send_input(profile, "worker", Some(&peer_wire)));

        // Drain it: popped → recorded as recently-claimed, no longer pending.
        let drained = orchestrator.drain_ready_continuations_for_session(
            &peer_wire,
            profile,
            MasterContinuationRuntimeState::idle(),
            4,
        );
        assert!(
            drained.iter().any(
                |c| matches!(&c.reason, MasterContinuationReason::External(k)
                if k == PEER_SEND_INPUT_EXTERNAL_KIND)
            ),
            "the injection must drain",
        );
        assert!(
            !orchestrator.has_pending_peer_send_input_for_peer(profile, "worker"),
            "a popped injection is no longer pending",
        );

        // ...but the combined check STILL blocks via the recent-claim record —
        // this is the closed TOCTOU window.
        assert!(
            orchestrator.peer_has_inflight_send_input(profile, "worker", Some(&peer_wire)),
            "a just-claimed (popped, not-yet-active) injection must still block",
        );

        // A DIFFERENT peer session's key stem must not match the claim.
        let other_wire = SessionKey::with_profile_topic(profile, "api", "peer-other", "peer-other");
        assert!(
            !orchestrator.peer_has_inflight_send_input(profile, "other", Some(&other_wire)),
            "a different peer session must not see this claim",
        );
        // With no target session, only the pending case is consulted (none now).
        assert!(!orchestrator.peer_has_inflight_send_input(profile, "worker", None));
    }

    /// codex DO-NOT-SHIP TOCTOU: on the WS path BOTH the legacy `on_failure`
    /// enqueue and the unified `on_terminal` enqueue fire SEQUENTIALLY inside
    /// one `mark_failed`, with the IDENTICAL
    /// `external/spawn_only_failure/<session>/<task>` dedupe key. If the AppUI
    /// continuation tick DRAINS the legacy enqueue before the unified one runs,
    /// the existing pending-map dedupe misses and one terminal transition
    /// would yield TWO recovery turns. This pins the full WS interleaving for
    /// an ACKED failure: legacy enqueue → tick drain → unified enqueue must
    /// total EXACTLY ONE recovery continuation.
    #[test]
    fn acked_spawn_only_failure_drain_between_legacy_and_unified_yields_exactly_one() {
        let orchestrator = default_agent_orchestrator();
        let session_id = SessionKey::with_profile("tenant-toctou-acked", "api", "spawn-fail-acked");
        let profile = "tenant-toctou-acked";
        let now = Utc::now();
        let task = octos_agent::BackgroundTask {
            id: "01900000-0000-7000-8000-00000000acked".into(),
            tool_name: "mofa_slides".into(),
            tool_call_id: "call-acked".into(),
            parent_session_key: Some(session_id.to_string()),
            child_session_key: None,
            child_terminal_state: None,
            child_join_state: None,
            child_joined_at: None,
            child_failure_action: None,
            task_ledger_path: None,
            status: octos_agent::TaskStatus::Failed,
            runtime_state: octos_agent::TaskRuntimeState::Failed,
            runtime_detail: None,
            started_at: now,
            updated_at: now,
            completed_at: Some(now),
            output_files: vec![],
            error: Some("plugin exited 137".into()),
            final_output: None,
            failed_by_observer: false,
            session_key: Some(session_id.to_string()),
            tool_input: Some(json!({"topic": "rust"})),
            originating_client_message_id: None,
            source: None,
            role: None,
            summary: None,
            artifact_count: None,
            runtime_policy_stamp: None,
            projection_metadata: None,
            workspace_root: None,
        };
        let signal = octos_agent::SpawnOnlyFailureSignal {
            task_id: task.id.clone(),
            tool_name: task.tool_name.clone(),
            tool_input: task.tool_input.clone().unwrap(),
            error_message: task.error.clone().unwrap(),
            suggested_alternatives: vec![],
            parent_session_key: task.parent_session_key.clone(),
            originating_client_message_id: None,
        };
        let event = octos_agent::TerminalEvent {
            task,
            // ACKED: the synth-ack fired, so the unified consumer renders the
            // recovery body (does NOT prompt-suppress).
            synth_ack_emitted: true,
            outcome: octos_agent::TerminalOutcome::Failed(signal.clone()),
        };

        // 1. Legacy `on_failure` WS enqueue (ui_protocol.rs set_on_failure_signal).
        let legacy =
            orchestrator.enqueue_spawn_only_failure_continuation(&session_id, profile, &signal);
        assert!(!legacy.is_duplicate(), "legacy enqueue should queue first");

        // 2. The 2s AppUI continuation tick DRAINS the legacy enqueue before
        //    `mark_failed` reaches `notify_terminal`.
        let drained = orchestrator.drain_ready_continuations_for_session(
            &session_id,
            profile,
            MasterContinuationRuntimeState::idle(),
            usize::MAX,
        );
        let recovery_drained = drained
            .iter()
            .filter(|item| {
                item.reason
                    == MasterContinuationReason::External(
                        SPAWN_ONLY_FAILURE_EXTERNAL_KIND.to_owned(),
                    )
            })
            .count();
        assert_eq!(recovery_drained, 1, "tick drains exactly one recovery turn");

        // 3. Unified `on_terminal` WS enqueue (route_terminal_event...Queue) —
        //    same transition, microseconds later. Must be collapsed by the
        //    recently-claimed guard, NOT produce a second recovery.
        route_terminal_event_to_continuation_queue(&event, Some(profile));
        assert_eq!(
            orchestrator.pending_continuation_count_for_session_for_test(&session_id, profile),
            0,
            "unified enqueue after the tick drain must NOT add a second recovery turn",
        );
    }

    /// fail-before-ack variant of the TOCTOU race. When a spawn_only task
    /// fails BEFORE its synth-ack is recorded, the unified `notify_terminal`
    /// samples `synth_ack_emitted = false` and PROMPT-SUPPRESSES the recovery
    /// (so unified alone would deliver ZERO). The legacy two-phase synth-ack
    /// stash re-emits the deferred `SpawnOnlyFailureSignal` on ack, and THAT
    /// legacy `on_failure` enqueue is the single delivery. Even if the tick
    /// drains the legacy enqueue before the (suppressed) unified path runs,
    /// the result must be EXACTLY ONE — not zero, not two.
    #[test]
    fn fail_before_ack_spawn_only_failure_yields_exactly_one() {
        let orchestrator = default_agent_orchestrator();
        let session_id =
            SessionKey::with_profile("tenant-toctou-preack", "api", "spawn-fail-preack");
        let profile = "tenant-toctou-preack";
        let now = Utc::now();
        let task = octos_agent::BackgroundTask {
            id: "01900000-0000-7000-8000-0000000preack".into(),
            tool_name: "mofa_slides".into(),
            tool_call_id: "call-preack".into(),
            parent_session_key: Some(session_id.to_string()),
            child_session_key: None,
            child_terminal_state: None,
            child_join_state: None,
            child_joined_at: None,
            child_failure_action: None,
            task_ledger_path: None,
            status: octos_agent::TaskStatus::Failed,
            runtime_state: octos_agent::TaskRuntimeState::Failed,
            runtime_detail: None,
            started_at: now,
            updated_at: now,
            completed_at: Some(now),
            output_files: vec![],
            error: Some("plugin binary missing".into()),
            final_output: None,
            failed_by_observer: false,
            session_key: Some(session_id.to_string()),
            tool_input: Some(json!({"topic": "rust"})),
            originating_client_message_id: None,
            source: None,
            role: None,
            summary: None,
            artifact_count: None,
            runtime_policy_stamp: None,
            projection_metadata: None,
            workspace_root: None,
        };
        let signal = octos_agent::SpawnOnlyFailureSignal {
            task_id: task.id.clone(),
            tool_name: task.tool_name.clone(),
            tool_input: task.tool_input.clone().unwrap(),
            error_message: task.error.clone().unwrap(),
            suggested_alternatives: vec![],
            parent_session_key: task.parent_session_key.clone(),
            originating_client_message_id: None,
        };
        // The unified terminal event for a fail-before-ack carries
        // `synth_ack_emitted = false` (the ack had not been recorded when the
        // event was built), which the consumer prompt-suppresses.
        let unified_event = octos_agent::TerminalEvent {
            task,
            synth_ack_emitted: false,
            outcome: octos_agent::TerminalOutcome::Failed(signal.clone()),
        };

        // 1. Unified `notify_terminal` fires first on the failed transition but
        //    PROMPT-SUPPRESSES (ack never emitted at fire time) → enqueues nothing.
        route_terminal_event_to_continuation_queue(&unified_event, Some(profile));
        assert_eq!(
            orchestrator.pending_continuation_count_for_session_for_test(&session_id, profile),
            0,
            "fail-before-ack unified path is prompt-suppressed (synth-ack never emitted)",
        );

        // 2. The legacy two-phase stash re-emits the deferred signal once the
        //    synth-ack is recorded (mark_synth_ack_emitted → on_failure). On the
        //    WS path that fires `enqueue_spawn_only_failure_continuation`.
        let legacy =
            orchestrator.enqueue_spawn_only_failure_continuation(&session_id, profile, &signal);
        assert!(
            !legacy.is_duplicate(),
            "the deferred legacy enqueue is the SINGLE delivery for fail-before-ack",
        );

        // 3. Tick drains it: exactly ONE recovery turn (not zero, not two).
        let drained = orchestrator.drain_ready_continuations_for_session(
            &session_id,
            profile,
            MasterContinuationRuntimeState::idle(),
            usize::MAX,
        );
        let recovery_drained = drained
            .iter()
            .filter(|item| {
                item.reason
                    == MasterContinuationReason::External(
                        SPAWN_ONLY_FAILURE_EXTERNAL_KIND.to_owned(),
                    )
            })
            .count();
        assert_eq!(
            recovery_drained, 1,
            "fail-before-ack must deliver EXACTLY ONE recovery continuation",
        );
        assert_eq!(
            orchestrator.pending_continuation_count_for_session_for_test(&session_id, profile),
            0,
            "no phantom second recovery left pending for fail-before-ack",
        );
    }

    /// mini5 soak regression (task-completion notice never fired): AppUI /
    /// TUI sessions use BARE session keys ("q5", "test1") with no
    /// `profile:channel:chat` prefix, so `SessionKey::profile_id()` is
    /// `None`. The terminal-agent continuation used to fall back to
    /// `MAIN_PROFILE_ID` ("_main"), which has no registered `ProfileRuntime`
    /// on the serve — so a profile-scoped connection skipped the
    /// continuation in `due_loop_targets` (profile mismatch) and an
    /// unscoped connection drained it into a `runtime_unavailable` turn.
    /// The reconciliation now threads the turn's real runtime profile, so
    /// the continuation is enqueued under THAT profile and re-entry fires.
    #[test]
    fn bare_key_background_task_continuation_inherits_runtime_profile_not_main_fallback() {
        let session_id = SessionKey("soak-bareprofile-1".into());
        assert_eq!(
            session_id.profile_id(),
            None,
            "precondition: AppUI session key carries no profile prefix"
        );
        let now = Utc::now();
        let task = octos_agent::BackgroundTask {
            id: "01900000-0000-7000-8000-0000000000c1".into(),
            tool_name: "spawn".into(),
            tool_call_id: "call-bp1".into(),
            parent_session_key: Some(session_id.to_string()),
            child_session_key: Some(format!("{session_id}#child-abc")),
            child_terminal_state: None,
            child_join_state: None,
            child_joined_at: None,
            child_failure_action: None,
            task_ledger_path: None,
            status: octos_agent::TaskStatus::Completed,
            runtime_state: octos_agent::TaskRuntimeState::Completed,
            runtime_detail: None,
            started_at: now,
            updated_at: now,
            completed_at: Some(now),
            output_files: Vec::new(),
            error: None,
            final_output: None,
            failed_by_observer: false,
            session_key: Some(session_id.to_string()),
            tool_input: None,
            originating_client_message_id: None,
            source: None,
            role: None,
            summary: Some("deep code review".into()),
            artifact_count: None,
            runtime_policy_stamp: None,
            projection_metadata: None,
            workspace_root: None,
        };

        // Reconcile under the profile the turn actually runs under ("coding"),
        // exactly as `forward_task_progress_to_channel` now threads it.
        let (mirrored_session, agent) = upsert_background_task_agent(&task, Some("coding"))
            .expect("terminal background task should mirror to an agent record");
        assert_eq!(mirrored_session, session_id);
        assert_eq!(
            agent["profile_id"],
            json!("coding"),
            "agent record must carry the runtime profile, not the _main fallback"
        );

        // The continuation must drain under the runtime profile — NOT "_main".
        let under_runtime_profile = default_agent_orchestrator()
            .drain_ready_continuations_for_session(
                &session_id,
                "coding",
                MasterContinuationRuntimeState::idle(),
                usize::MAX,
            );
        assert!(
            under_runtime_profile
                .iter()
                .any(|item| item.reason == MasterContinuationReason::ChildCompleted),
            "ChildCompleted continuation must be drainable under the runtime profile 'coding'"
        );
        assert!(
            under_runtime_profile
                .iter()
                .all(|item| item.profile_id.as_str() == "coding"),
            "every drained continuation must be tagged with the runtime profile, got {:?}",
            under_runtime_profile
                .iter()
                .map(|item| item.profile_id.as_str().to_owned())
                .collect::<Vec<_>>()
        );

        // And nothing must linger under the broken "_main" fallback profile.
        let under_main = default_agent_orchestrator().drain_ready_continuations_for_session(
            &session_id,
            MAIN_PROFILE_ID,
            MasterContinuationRuntimeState::idle(),
            usize::MAX,
        );
        assert!(
            under_main.is_empty(),
            "no continuation may be stranded under the '_main' fallback, got {:?}",
            under_main
                .iter()
                .map(|item| item.reason.clone())
                .collect::<Vec<_>>()
        );
    }

    /// mini5 soak gap #1: the server-level drain
    /// (`spawn_global_master_continuation_drain`) sweeps `due_loop_targets`
    /// with `profile_filter = None` precisely so it surfaces continuations that
    /// a connection scoped to a DIFFERENT profile would skip — i.e. it drains
    /// for sessions that have no matching live connection. A per-connection
    /// tick filtered to profile Q misses a continuation enqueued under profile
    /// P; the connection-independent None sweep catches it.
    #[test]
    fn unscoped_due_loop_targets_surfaces_continuation_a_scoped_connection_skips() {
        let orchestrator = InProcessAgentOrchestrator::default();
        let session_id = SessionKey("gap1-unscoped-sweep".into());
        orchestrator.upsert_agent(AgentUpsert {
            agent_id: "child-x".into(),
            parent_agent_id: Some("master".into()),
            session_id: session_id.clone(),
            task_id: None,
            path: "master/child-x".into(),
            role: "worker".into(),
            nickname: "Xena".into(),
            backend_kind: "native".into(),
            status: "completed".into(),
            last_task: Some("done".into()),
            cwd: None,
            profile_id: "coding".into(),
        });

        // A connection scoped to a DIFFERENT profile never surfaces it — this
        // is the gap: with no coding-scoped connection open, nothing drains it.
        let scoped_other = orchestrator.due_loop_targets(Some("ocean"), 8);
        assert!(
            !scoped_other
                .iter()
                .any(|(session, _)| *session == session_id),
            "a connection scoped to a different profile must not surface the continuation, got {scoped_other:?}"
        );

        // The server-level None sweep surfaces it regardless of profile, so the
        // global drain loop can run it even when no client is connected.
        let unscoped = orchestrator.due_loop_targets(None, 8);
        assert!(
            unscoped
                .iter()
                .any(|(session, profile)| *session == session_id && profile == "coding"),
            "the connection-independent (None) sweep must surface the queued continuation, got {unscoped:?}"
        );
    }

    /// codex e1f611f4 re-review (filter-before-limit): the global drain's
    /// workspace gate is applied INSIDE `due_loop_targets_with_filter` BEFORE
    /// the `max_items` limit, so a non-runnable (deferred / workspace-unknown)
    /// session can never consume a result slot and starve a runnable one behind
    /// it — even at `max_items == 1`. This replaces the unbounded `usize::MAX`
    /// scan with a bounded result + no starvation.
    #[test]
    fn filtered_due_loop_targets_skips_non_runnable_before_the_limit() {
        let orchestrator = InProcessAgentOrchestrator::default();
        let deferred = SessionKey("gap1-deferred-no-workspace".into());
        let runnable = SessionKey("gap1-runnable-has-workspace".into());
        for (session, agent_id) in [(&deferred, "child-d"), (&runnable, "child-r")] {
            orchestrator.upsert_agent(AgentUpsert {
                agent_id: agent_id.to_string(),
                parent_agent_id: Some("master".into()),
                session_id: session.clone(),
                task_id: None,
                path: format!("master/{agent_id}"),
                role: "worker".into(),
                nickname: "w".into(),
                backend_kind: "native".into(),
                status: "completed".into(),
                last_task: Some("done".into()),
                cwd: None,
                profile_id: "coding".into(),
            });
        }

        // Only `runnable` passes the predicate; `deferred` must be skipped
        // WITHOUT consuming the single slot.
        let is_runnable = |session: &SessionKey, _profile_id: &str| *session == runnable;
        let targets = orchestrator.due_loop_targets_with_filter(None, 1, Some(&is_runnable));
        assert_eq!(
            targets,
            vec![(runnable.clone(), "coding".to_owned())],
            "the non-runnable session must be dropped before the limit so the runnable one is not starved, got {targets:?}"
        );
    }

