    /// Bullet 3: budget exhaustion → enqueue a wrap-up turn AND
    /// transition the goal to `budget_limited`. Subsequent calls must
    /// be idempotent (no duplicate wrap-up).
    /// #1696 — the model-owned transition matrix: complete|blocked only,
    /// profile-scoped, refuses double-complete; the post-turn budget flip
    /// must not overwrite a mid-turn model transition.
    #[test]
    fn model_create_goal_refuses_interleaved_double_create() {
        // #1935 codex round 7 — `model_create_goal` checks "no unfinished
        // goal" under one lock but delegates the create to `set_goal`, which
        // RE-locks: two parallel creates both passed the pre-check (both saw
        // the key empty after their remove), and the loser landed in
        // `set_goal`'s UPDATE branch, silently overwriting the winner's
        // objective. The admission is now enforced atomically inside
        // `set_goal` for model intent; this test drives the loser's exact
        // interleaved second half at the orchestrator seam.
        let orchestrator = InProcessAgentOrchestrator::default();
        let session_id = SessionKey::with_profile("tenant-a", "api", "goal-create-race");
        orchestrator
            .model_create_goal(
                &session_id,
                "tenant-a",
                "objective A (winner)",
                Some(10_000),
            )
            .expect("first create succeeds");

        // The interleaved loser already passed the pre-check while the
        // winner's goal did not exist yet; its delegated `set_goal` (model
        // intent) now runs against the winner's ACTIVE goal and must refuse
        // under the admission lock itself.
        let err = orchestrator
            .set_goal(GoalSetRequest {
                session_id: session_id.clone(),
                profile_id: "tenant-a".into(),
                objective: "objective B (loser)".into(),
                status: Some("active".into()),
                token_budget: Some(10_000),
                transition_actor: Some("model".into()),
            })
            .expect_err("interleaved model create must refuse, not overwrite");
        assert!(
            err.message.contains("unfinished goal"),
            "loser gets the unfinished-goal refusal: {}",
            err.message,
        );

        // A sequential second create still refuses at the pre-check.
        let err = orchestrator
            .model_create_goal(&session_id, "tenant-a", "objective C", None)
            .expect_err("sequential second create refuses");
        assert!(err.contains("unfinished goal"), "pre-check refusal: {err}");

        // The winner's objective stands untouched.
        let snapshot = orchestrator
            .goal_verification_snapshot(&session_id, "tenant-a")
            .expect("winner's goal exists");
        assert_eq!(snapshot.objective, "objective A (winner)");

        // User-path replace semantics are UNCHANGED: a user edit of the
        // unfinished goal still lands.
        orchestrator
            .set_goal(GoalSetRequest {
                session_id: session_id.clone(),
                profile_id: "tenant-a".into(),
                objective: "objective A (user-edited)".into(),
                status: Some("active".into()),
                token_budget: None,
                transition_actor: None,
            })
            .expect("user replace still works");
    }

    #[tokio::test]
    async fn model_create_goal_gates_on_unfinished_goal() {
        let orchestrator = InProcessAgentOrchestrator::default();
        let session_id = SessionKey::with_profile("tenant-a", "api", "goal-create");

        // No goal yet → the model may create one; it starts active.
        let goal = orchestrator
            .model_create_goal(
                &session_id,
                "tenant-a",
                "  improve onboarding UX  ",
                Some(2_000),
            )
            .expect("create when none exists");
        assert_eq!(goal["status"], json!("active"));
        let first_goal_id = goal["goal_id"].as_str().expect("goal_id").to_owned();

        // An UNFINISHED goal blocks a second create (codex parity).
        let err = orchestrator
            .model_create_goal(&session_id, "tenant-a", "start something else", None)
            .expect_err("must reject while a goal is unfinished");
        assert!(err.contains("unfinished goal"), "reason: {err}");

        // Wrong profile and empty objective are rejected.
        assert!(
            orchestrator
                .model_create_goal(&session_id, "tenant-b", "x", None)
                .is_err()
        );
        assert!(
            orchestrator
                .model_create_goal(&session_id, "tenant-a", "   ", None)
                .is_err()
        );

        // Spend tokens on the first goal so the reuse bug (carried-over
        // counters) would be observable if it regressed.
        orchestrator.force_goal_tokens_used_for_test(&session_id, 1_500);

        // Once COMPLETE, the model may replace it with a fresh active goal.
        orchestrator
            .model_transition_goal(&session_id, "tenant-a", "complete", "done", None)
            .await
            .expect("complete the goal");
        let replaced = orchestrator
            .model_create_goal(&session_id, "tenant-a", "next objective", None)
            .expect("replace a complete goal");
        assert_eq!(replaced["status"], json!("active"));
        // Fix B: replacing a complete goal MUST mint a fresh goal identity and
        // reset the counters, not reuse the finished record's goal_id / spend.
        let second_goal_id = replaced["goal_id"].as_str().expect("goal_id");
        assert_ne!(
            second_goal_id, first_goal_id,
            "a replacement goal must get a fresh goal_id, not reuse the completed one"
        );
        assert_eq!(
            replaced["tokens_used"],
            json!(0),
            "the replacement goal's token counter must be reset to zero"
        );
        assert_eq!(
            replaced["objective"],
            json!("next objective"),
            "the replacement carries the new objective"
        );
    }

    /// #1975 — the USER path (`set_goal` with the default "user" actor, i.e. the
    /// `/goal` command) must mint a FRESH goal_id with zeroed counters when it
    /// replaces a COMPLETE goal — exactly like the model path (Fix B). The bug:
    /// `set_goal`'s update branch resurrected the finished record, carrying its
    /// goal_id and spent `tokens_used` into the new budget (a fresh 300K budget
    /// "born 85% spent") and landing new activity in the old goal's ledger file,
    /// whose complete-protection then rejects the active-state refreshes.
    #[tokio::test]
    async fn should_mint_fresh_goal_id_and_reset_tokens_when_user_replaces_complete_goal() {
        let orchestrator = InProcessAgentOrchestrator::default();
        let session_id = SessionKey::with_profile("tenant-user-reuse", "api", "goal-set");

        // USER create (transition_actor defaults to "user").
        let first = orchestrator
            .set_goal(GoalSetRequest {
                session_id: session_id.clone(),
                profile_id: "tenant-user-reuse".to_owned(),
                objective: "first objective".to_owned(),
                status: Some("active".to_owned()),
                token_budget: Some(2_000),
                transition_actor: None,
            })
            .expect("user create when none exists");
        let first_goal_id = first["goal"]["goal_id"]
            .as_str()
            .expect("goal_id")
            .to_owned();

        // Spend tokens, then complete it so the carried-over spend is observable.
        orchestrator.force_goal_tokens_used_for_test(&session_id, 1_500);
        orchestrator
            .model_transition_goal(&session_id, "tenant-user-reuse", "complete", "done", None)
            .await
            .expect("complete the goal");

        // USER replace of the COMPLETE goal — must mint a fresh identity.
        let replaced = orchestrator
            .set_goal(GoalSetRequest {
                session_id: session_id.clone(),
                profile_id: "tenant-user-reuse".to_owned(),
                objective: "next objective".to_owned(),
                status: Some("active".to_owned()),
                token_budget: Some(300_000),
                transition_actor: None,
            })
            .expect("user replace of a complete goal");

        assert_ne!(
            replaced["goal"]["goal_id"].as_str().expect("goal_id"),
            first_goal_id,
            "a user replace of a complete goal must mint a fresh goal_id, not reuse the finished one"
        );
        assert_eq!(
            replaced["goal"]["tokens_used"],
            json!(0),
            "the replacement goal's token counter must reset to zero, not carry the finished goal's spend"
        );
        assert_eq!(replaced["goal"]["status"], json!("active"));
        assert_eq!(
            replaced["goal"]["objective"],
            json!("next objective"),
            "the replacement carries the new objective"
        );
    }

    #[tokio::test]
    async fn model_transition_goal_enforces_ownership_matrix() {
        let orchestrator = InProcessAgentOrchestrator::default();
        let session_id = SessionKey::with_profile("tenant-a", "api", "goal-tool");
        orchestrator
            .set_goal(GoalSetRequest {
                session_id: session_id.clone(),
                profile_id: "tenant-a".into(),
                objective: "write the haiku".into(),
                status: Some("active".into()),
                token_budget: Some(1_000),
                transition_actor: None,
            })
            .expect("set active goal");

        // User/system-owned statuses are rejected server-side.
        for status in ["paused", "active", "budget_limited", "cleared"] {
            assert!(
                orchestrator
                    .model_transition_goal(&session_id, "tenant-a", status, "nope", None)
                    .await
                    .is_err(),
                "{status} must not be a model-allowed transition"
            );
        }
        // Wrong profile is rejected.
        assert!(
            orchestrator
                .model_transition_goal(&session_id, "tenant-b", "complete", "scope", None)
                .await
                .is_err()
        );

        // complete works and returns the goal snapshot.
        let goal = orchestrator
            .model_transition_goal(&session_id, "tenant-a", "complete", "haiku written", None)
            .await
            .expect("model completes");
        assert_eq!(goal["status"], json!("complete"));
        assert_eq!(
            orchestrator.goal_status_for_test(&session_id).as_deref(),
            Some("complete")
        );
        // Double-complete refused.
        assert!(
            orchestrator
                .model_transition_goal(&session_id, "tenant-a", "complete", "again", None)
                .await
                .is_err()
        );

        // The post-turn accountant for the SAME turn (which crosses the
        // budget) must not overwrite the model's terminal state with
        // budget_limited.
        orchestrator.force_goal_tokens_used_for_test(&session_id, 900);
        orchestrator.record_goal_turn(&session_id, "tenant-a", None, 500, 5);
        assert_eq!(
            orchestrator.goal_status_for_test(&session_id).as_deref(),
            Some("complete"),
            "budget flip must not clobber a model-set terminal status"
        );
    }

    /// #1957 — a model `goal_update` completion must land in the DURABLE goal
    /// ledger, not just the in-memory record. Before this fix a goal that
    /// completed without ever recording a peer finding left the ledger's goals
    /// row stuck at `active`; `model_transition_goal` now syncs the transition
    /// straight from the snapshot it just flipped (no re-fetch → codex #3).
    #[tokio::test]
    async fn model_transition_goal_syncs_final_status_into_the_ledger() {
        let orchestrator = InProcessAgentOrchestrator::default();
        let data_dir = tempfile::TempDir::new().unwrap();
        let session_id = SessionKey::with_profile("tenant-a", "api", "goal-ledger-sync");
        orchestrator
            .set_goal(GoalSetRequest {
                session_id: session_id.clone(),
                profile_id: "tenant-a".into(),
                objective: "prove the ledger reflects completion".into(),
                status: Some("active".into()),
                token_budget: Some(1_000),
                transition_actor: None,
            })
            .expect("set active goal");
        let goal_id = orchestrator
            .goal_id_for_session(&session_id)
            .expect("goal_id");

        // Complete via the model path WITH the profile data dir → must sync.
        // Note: no peer finding was ever recorded for this goal, so the ledger
        // row is created for the FIRST time by the transition sync itself.
        orchestrator
            .model_transition_goal(
                &session_id,
                "tenant-a",
                "complete",
                "objective met",
                Some(data_dir.path()),
            )
            .await
            .expect("model completes");

        let ledger_path = InProcessAgentOrchestrator::goal_ledger_dir(data_dir.path())
            .join(format!("{}.db", sanitize_filename_for_ledger(&goal_id)));
        let ledger = octos_fleet::GoalLedger::open(&ledger_path).expect("open ledger");
        let row = ledger
            .get_goal(&goal_id)
            .expect("query ledger")
            .expect("goal row present in ledger");
        assert_eq!(
            row.status, "complete",
            "the durable ledger must reflect the final `complete` status"
        );
        assert_eq!(row.objective, "prove the ledger reflects completion");
    }

    /// #1967 test helper — seed a goal ledger at
    /// `<data_dir>/goal-ledgers/<goal_id>.db` with its goals row, returning
    /// the opened ledger for direct escalation writes.
    fn seed_goal_ledger(data_dir: &std::path::Path, goal_id: &str) -> octos_fleet::GoalLedger {
        let ledger_dir = InProcessAgentOrchestrator::goal_ledger_dir(data_dir);
        std::fs::create_dir_all(&ledger_dir).unwrap();
        let ledger = octos_fleet::GoalLedger::open(
            ledger_dir.join(format!("{}.db", sanitize_filename_for_ledger(goal_id))),
        )
        .expect("open ledger");
        ledger
            .upsert_goal(&octos_fleet::Goal {
                goal_id: goal_id.to_owned(),
                objective: "escalation lifecycle".to_owned(),
                status: "active".to_owned(),
                tokens_used: 0,
                token_budget: 1_000,
                time_used_seconds: 0,
                continuations_used: 0,
                revision: 0,
                created_at_ms: 1_000,
                updated_at_ms: 1_000,
            })
            .expect("goals row");
        ledger
    }

    /// #1967 test helper — an OPEN escalation row for the sweeps/surfaces.
    fn open_escalation_row(
        escalation_id: &str,
        goal_id: &str,
        peer_id: &str,
        question: &str,
        created_at_ms: u64,
        default_action: Option<&str>,
        default_after_secs: Option<i64>,
    ) -> octos_fleet::Escalation {
        octos_fleet::Escalation {
            escalation_id: escalation_id.to_owned(),
            goal_id: goal_id.to_owned(),
            task_id: None,
            peer_id: peer_id.to_owned(),
            question: question.to_owned(),
            context: None,
            status: "open".to_owned(),
            default_action: default_action.map(str::to_owned),
            default_after_secs,
            created_at_ms,
            resolved_at_ms: None,
            resolved_by: None,
            resolution: None,
        }
    }

    /// #1967 — `goal_get`'s escalation surface: open rows come back in the
    /// compact shape the tool folds in (escalation_id, peer_id, task_id,
    /// question capped at 300 chars, created_at_ms, age_seconds,
    /// default_action, default_after_secs), oldest first; resolved rows and
    /// a missing ledger yield nothing.
    #[test]
    fn model_goal_ledger_open_escalations_shape_and_truncation() {
        let orchestrator = InProcessAgentOrchestrator::default();
        let data_dir = tempfile::TempDir::new().unwrap();
        // No ledger file yet → empty, not an error.
        assert!(
            orchestrator
                .model_goal_ledger_open_escalations(data_dir.path(), "g-esc")
                .is_empty()
        );
        let ledger = seed_goal_ledger(data_dir.path(), "g-esc");
        let now_ms = now_ms_u64();
        ledger
            .append_escalation(&open_escalation_row(
                "esc-newer",
                "g-esc",
                "peer-b",
                &"q".repeat(400),
                now_ms.saturating_sub(5_000),
                Some("proceed"),
                Some(300),
            ))
            .unwrap();
        ledger
            .append_escalation(&open_escalation_row(
                "esc-older",
                "g-esc",
                "peer-a",
                "[question] which port?",
                now_ms.saturating_sub(60_000),
                None,
                None,
            ))
            .unwrap();
        // A resolved row must never surface.
        ledger
            .append_escalation(&open_escalation_row(
                "esc-done", "g-esc", "peer-c", "answered", 1_000, None, None,
            ))
            .unwrap();
        ledger
            .resolve_escalation("peer-c", "[answer] yes", "master", 2_000)
            .unwrap();

        let rows = orchestrator.model_goal_ledger_open_escalations(data_dir.path(), "g-esc");
        assert_eq!(rows.len(), 2, "open rows only");
        assert_eq!(rows[0]["escalation_id"], json!("esc-older"), "oldest first");
        assert_eq!(rows[0]["peer_id"], json!("peer-a"));
        assert_eq!(rows[0]["question"], json!("[question] which port?"));
        assert_eq!(rows[0]["task_id"], Value::Null);
        assert_eq!(rows[0]["default_action"], Value::Null);
        assert_eq!(rows[0]["default_after_secs"], Value::Null);
        let age = rows[0]["age_seconds"].as_u64().expect("age_seconds");
        assert!((30..=600).contains(&age), "age ≈ 60s, got {age}");
        // #1967 codex round — the 400-char question is capped at 300 chars
        // INCLUDING the ellipsis (299 + '…'), never 301: the surface's ≤300
        // contract holds for the whole rendered string.
        let question = rows[1]["question"].as_str().expect("question");
        assert_eq!(
            question.chars().count(),
            300,
            "cap is ≤300 INCLUDING the ellipsis"
        );
        assert_eq!(question, format!("{}…", "q".repeat(299)));
        assert_eq!(rows[1]["default_action"], json!("proceed"));
        assert_eq!(rows[1]["default_after_secs"], json!(300));
        assert_eq!(
            rows[1]["created_at_ms"],
            json!(now_ms.saturating_sub(5_000))
        );
        // Boundary: an EXACTLY-300-char question passes through untruncated —
        // no ellipsis burned on a question already within the cap.
        ledger
            .append_escalation(&open_escalation_row(
                "esc-exact",
                "g-esc",
                "peer-d",
                &"e".repeat(300),
                now_ms,
                None,
                None,
            ))
            .unwrap();
        let rows = orchestrator.model_goal_ledger_open_escalations(data_dir.path(), "g-esc");
        let exact = rows
            .iter()
            .find(|r| r["escalation_id"] == json!("esc-exact"))
            .expect("esc-exact listed");
        assert_eq!(exact["question"], json!("e".repeat(300)));
    }

    /// #1967 — the timeout resolution string carries the producer's declared
    /// default (or the "expired" placeholder) so the master can tell WHAT the
    /// timeout committed the peer to.
    #[test]
    fn escalation_timeout_resolution_names_default_or_expired() {
        assert_eq!(
            escalation_timeout_resolution(Some("proceed with plan A")),
            "[timeout] proceed with plan A"
        );
        assert_eq!(escalation_timeout_resolution(None), "[timeout] expired");
    }

    /// #1967 — `sweep_escalation_timeouts` resolves ONLY open escalations
    /// whose `default_after_secs` has elapsed; unexpired and no-default rows
    /// stay open, and a second pass is a no-op (idempotent).
    #[test]
    fn sweep_escalation_timeouts_resolves_only_elapsed_defaults() {
        let orchestrator = InProcessAgentOrchestrator::default();
        let data_dir = tempfile::TempDir::new().unwrap();
        // No goal-ledgers dir at all → nothing to sweep.
        assert_eq!(orchestrator.sweep_escalation_timeouts(data_dir.path()), 0);
        let ledger = seed_goal_ledger(data_dir.path(), "g-sweep");
        let now_ms = now_ms_u64();
        // Expired: created 10s ago with a 1s default.
        ledger
            .append_escalation(&open_escalation_row(
                "esc-expired",
                "g-sweep",
                "p1",
                "waited too long",
                now_ms.saturating_sub(10_000),
                Some("proceed"),
                Some(1),
            ))
            .unwrap();
        // Unexpired: created now with a 1h default.
        ledger
            .append_escalation(&open_escalation_row(
                "esc-later",
                "g-sweep",
                "p2",
                "still fresh",
                now_ms,
                None,
                Some(3_600),
            ))
            .unwrap();
        // No default → the sweep must never touch it.
        ledger
            .append_escalation(&open_escalation_row(
                "esc-forever",
                "g-sweep",
                "p3",
                "needs a human",
                now_ms.saturating_sub(10_000),
                None,
                None,
            ))
            .unwrap();

        assert_eq!(
            orchestrator.sweep_escalation_timeouts(data_dir.path()),
            1,
            "exactly the elapsed default resolves"
        );
        let still_open = ledger.list_open_escalations("g-sweep").unwrap();
        assert_eq!(
            still_open
                .iter()
                .map(|e| e.escalation_id.as_str())
                .collect::<Vec<_>>(),
            // Oldest first: esc-forever (now-10s) precedes esc-later (now).
            vec!["esc-forever", "esc-later"],
            "unexpired + no-default rows stay open"
        );
        assert_eq!(
            orchestrator.sweep_escalation_timeouts(data_dir.path()),
            0,
            "second pass is a no-op"
        );
    }

    /// #1967 codex round — `GoalLedger::open` MUTATES its target (WAL pragma
    /// switch + DDL), so the sweep must never follow a symlinked entry out of
    /// `goal-ledgers/`: a planted link would let the scan initialize/flip
    /// tables in an arbitrary sqlite file. Same fail-closed posture as
    /// `staged_peer_dir`.
    #[cfg(unix)]
    #[test]
    fn sweep_escalation_timeouts_skips_symlinked_ledgers() {
        let orchestrator = InProcessAgentOrchestrator::default();
        let data_dir = tempfile::TempDir::new().unwrap();
        // A REAL ledger with an expired-default row lives OUTSIDE the
        // goal-ledgers dir; only a symlink points at it from inside.
        let outside = data_dir.path().join("outside");
        std::fs::create_dir_all(&outside).unwrap();
        let target_db = outside.join("foreign.db");
        let foreign = octos_fleet::GoalLedger::open(&target_db).expect("open foreign ledger");
        foreign
            .upsert_goal(&octos_fleet::Goal {
                goal_id: "g-foreign".to_owned(),
                objective: "not ours".to_owned(),
                status: "active".to_owned(),
                tokens_used: 0,
                token_budget: 1_000,
                time_used_seconds: 0,
                continuations_used: 0,
                revision: 0,
                created_at_ms: 1_000,
                updated_at_ms: 1_000,
            })
            .unwrap();
        foreign
            .append_escalation(&open_escalation_row(
                "esc-foreign",
                "g-foreign",
                "p1",
                "expired elsewhere",
                now_ms_u64().saturating_sub(10_000),
                Some("proceed"),
                Some(1),
            ))
            .unwrap();
        let ledger_dir = InProcessAgentOrchestrator::goal_ledger_dir(data_dir.path());
        std::fs::create_dir_all(&ledger_dir).unwrap();
        std::os::unix::fs::symlink(&target_db, ledger_dir.join("linked.db")).unwrap();

        assert_eq!(
            orchestrator.sweep_escalation_timeouts(data_dir.path()),
            0,
            "a symlinked ledger entry must be skipped, not opened"
        );
        assert_eq!(
            foreign.list_open_escalations("g-foreign").unwrap().len(),
            1,
            "the link target's row must remain untouched"
        );
    }

    /// #1945 — `model_goal_ledger_digest` reduces the durable ledger to a
    /// fixed-size compact summary (task counts by status, finding counts by
    /// lifecycle/kind, total cost) that `goal_get` folds in as
    /// `ledger_digest`. No ledger file → `None` (absent, not zeros), so a
    /// fresh goal adds nothing to the snapshot.
    ///
    /// codex round — this test drives the REAL production writer
    /// ([`InProcessAgentOrchestrator::model_goal_record_peer_finding`]), not
    /// hand-crafted SQL rows, and asserts what production actually produces:
    /// `running` task stubs (nothing updates task status today) and
    /// `observed`/`observation` findings whose `cost_tokens` carry the real
    /// #1965 per-turn charges. The finding WITHOUT a task_id is the
    /// load-bearing case twice over: the path digest's `cost_by_path`
    /// dropped such rows, which is why the digest is computed from direct
    /// SQL aggregates.
    /// #2036 follow-up — a peer's review must reach the DURABLE row intact.
    ///
    /// Found by a real two-peer review soak on merged main, not by a unit test:
    /// #2036 raised the transport-side cap from 400 to 4000, but this writer
    /// still applied a hard `take(500)`, so real findings came out at exactly
    /// 500 characters — cut mid-token and unmarked, which is the same
    /// unverifiable fragment the 400-char cut produced. Each cap was tested in
    /// isolation and both looked fine; only the end-to-end path showed that the
    /// inner one binds.
    ///
    /// Drives the production writer and reads back through the same accessor
    /// the completion verifier uses.
    #[test]
    fn a_long_peer_review_reaches_the_ledger_row_intact() {
        let orchestrator = InProcessAgentOrchestrator::default();
        let data_dir = tempfile::TempDir::new().unwrap();
        let wire = "tenant-a:api:long-peer-review";
        let session_id = SessionKey(wire.to_owned());
        orchestrator
            .set_goal(GoalSetRequest {
                session_id: session_id.clone(),
                profile_id: "tenant-a".into(),
                objective: "review two modules".into(),
                status: Some("active".into()),
                token_budget: Some(10_000),
                transition_actor: None,
            })
            .expect("set active goal");
        let goal_id = orchestrator
            .goal_id_for_session(&session_id)
            .expect("goal_id");

        // The shape that failed live: a multi-finding security review, far
        // longer than any per-sentence budget but well inside the real one.
        let mut review = String::from("Security review of ssrf.rs — findings:\n");
        for i in 0..12 {
            review.push_str(&format!(
                "{i}. HIGH — the guard resolves the host before checking it, so a \
                 DNS entry that flips between a public and a private address \
                 between the check and the fetch slips through; see the \
                 resolve/connect gap.\n"
            ));
        }
        review.push_str("END-OF-REVIEW-MARKER");
        assert!(
            review.chars().count() > 1_000,
            "fixture must be far longer than the OLD 500-char cap, or it proves \
             nothing: {}",
            review.chars().count()
        );

        orchestrator
            .model_goal_record_peer_finding(
                data_dir.path(),
                &goal_id,
                "tenant-a",
                wire,
                "rev-ssrf",
                None,
                &review,
                1_200,
            )
            .expect("finding recorded");

        let findings = orchestrator.model_goal_ledger_findings(data_dir.path(), &goal_id);
        let stored = findings
            .first()
            .and_then(|f| f.get("assertion"))
            .and_then(|a| a.as_str())
            .expect("one finding with an assertion");

        assert!(
            stored.contains("END-OF-REVIEW-MARKER"),
            "the END of the review must survive — a cap here silently drops the \
             findings the verifier is asked to judge; stored {} chars",
            stored.chars().count()
        );
        assert!(
            !stored.contains("…[truncated]"),
            "an ordinary review must not be abridged at all: {stored}"
        );
    }

    #[test]
    fn model_goal_ledger_digest_reduces_the_ledger_to_compact_counts() {
        let orchestrator = InProcessAgentOrchestrator::default();
        let data_dir = tempfile::TempDir::new().unwrap();
        assert!(
            orchestrator
                .model_goal_ledger_digest(data_dir.path(), "g-digest")
                .is_none(),
            "no ledger file → None"
        );

        let wire = "tenant-a:api:goal-ledger-digest";
        let session_id = SessionKey(wire.to_owned());
        orchestrator
            .set_goal(GoalSetRequest {
                session_id: session_id.clone(),
                profile_id: "tenant-a".into(),
                objective: "digest me".into(),
                status: Some("active".into()),
                token_budget: Some(10_000),
                transition_actor: None,
            })
            .expect("set active goal");
        let goal_id = orchestrator
            .goal_id_for_session(&session_id)
            .expect("goal_id");

        // Record two peer findings through the production path: one staged
        // WITH a fleet task (creates the `running` FK stub row) charging 450
        // tokens (#1965), one WITHOUT a task_id — the common peer_handoff
        // case — charging 250. Both charges must land in the digest total.
        orchestrator
            .model_goal_record_peer_finding(
                data_dir.path(),
                &goal_id,
                "tenant-a",
                wire,
                "peer-alpha",
                Some("t1"),
                "explored the API surface",
                450,
            )
            .expect("task-scoped finding recorded");
        orchestrator
            .model_goal_record_peer_finding(
                data_dir.path(),
                &goal_id,
                "tenant-a",
                wire,
                "peer-beta",
                None,
                "no fleet task, still counted",
                250,
            )
            .expect("task-less finding recorded");

        let digest = orchestrator
            .model_goal_ledger_digest(data_dir.path(), &goal_id)
            .expect("ledger exists → digest present");
        // Only the `running` stub exists — production never updates task
        // status today (honest semantics, see model_goal_ledger_digest).
        assert_eq!(digest["tasks"], json!({"running": 1}));
        assert_eq!(
            digest["findings"]["total"],
            json!(2),
            "the task-less finding is counted too — the regression the SQL \
             aggregates exist to prevent"
        );
        assert_eq!(digest["findings"]["by_lifecycle"], json!({"observed": 2}));
        assert_eq!(digest["findings"]["by_kind"], json!({"observation": 2}));
        // #1965 — the digest total sums BOTH charges, including the task-less
        // row the old `cost_by_path` roll-up dropped (450 + 250).
        assert_eq!(digest["cost_tokens"], json!(700));

        // A DIFFERENT goal id under the same data dir has its own file → None.
        assert!(
            orchestrator
                .model_goal_ledger_digest(data_dir.path(), "g-other")
                .is_none()
        );
    }

