    /// #1696 — the GoalContinue prompt must teach the goal protocol (the
    /// sentinel era never told the model how to declare success).
    #[test]
    fn goal_continuation_prompt_teaches_goal_tools() {
        let orchestrator = InProcessAgentOrchestrator::default();
        let session_id = SessionKey::with_profile("tenant-a", "api", "goal-prompt");
        orchestrator
            .set_goal(GoalSetRequest {
                session_id: session_id.clone(),
                profile_id: "tenant-a".into(),
                objective: "write the haiku".into(),
                status: Some("active".into()),
                token_budget: Some(2_000_000),
                transition_actor: None,
            })
            .expect("set active goal enqueues the initial continuation");
        let drained = orchestrator.drain_ready_continuations_for_session(
            &session_id,
            "tenant-a",
            MasterContinuationRuntimeState::idle(),
            usize::MAX,
        );
        assert_eq!(drained.len(), 1, "initial GoalContinue drains");
        let prompt = master_continuation_prompt(&drained[0]);
        assert!(prompt.contains("goal_update"), "teach the transition tool");
        assert!(prompt.contains("goal_get"), "teach the read tool");
        assert!(
            prompt.contains("redefine the goal"),
            "anti-scope-shrink language present"
        );
        assert!(
            prompt.contains("nearly exhausted") || prompt.contains("stopping work"),
            "anti-premature-complete (budget-exhaustion) language present"
        );
        // Richer codex-parity steering (task 4): fidelity + completion audit.
        assert!(
            prompt.contains("Fidelity"),
            "fidelity steering present: {prompt}"
        );
        assert!(
            prompt.contains("Completion audit"),
            "completion-audit steering present: {prompt}"
        );
        assert!(
            prompt.contains("UNPROVEN"),
            "completion treated as unproven: {prompt}"
        );
        // Tangent-pollution mitigation (task 5).
        assert!(
            prompt.contains("unrelated to this objective"),
            "tangent-pollution guard present: {prompt}"
        );
    }

    /// Task 1 (mini5 seq-454 "orchestrating while idle") + codex MED (lossy
    /// mapping): the supervised group status must MIRROR the goal's real
    /// lifecycle status. Only an `active` goal is `Running`; a `budget_limited`
    /// / `paused` / `blocked` goal must read as a PRECISE non-Running state so
    /// the roster neither renders "Orchestrating…" on an idle session nor
    /// mislabels a paused goal as cancelled or a blocked goal as failed.
    #[test]
    fn group_status_mirrors_goal_lifecycle_status() {
        assert_eq!(group_status_for_goal("active"), GroupStatus::Running);
        assert_eq!(group_status_for_goal("complete"), GroupStatus::Completed);
        assert_eq!(group_status_for_goal("cleared"), GroupStatus::Completed);
        // Precise non-running states, not lossy Failed/Cancelled collapses.
        assert_eq!(group_status_for_goal("blocked"), GroupStatus::Blocked);
        assert_eq!(
            group_status_for_goal("budget_limited"),
            GroupStatus::BudgetLimited
        );
        assert_eq!(group_status_for_goal("paused"), GroupStatus::Paused);
        // #25 — `archived` is a terminal stop, rendered as a clean
        // `Completed` (never Running, never a failure/cancellation).
        assert_eq!(group_status_for_goal("archived"), GroupStatus::Completed);
        // The core regression across every non-active state: NOT Running.
        for stopped in ["budget_limited", "paused", "blocked"] {
            assert_ne!(
                group_status_for_goal(stopped),
                GroupStatus::Running,
                "{stopped} goal must not read as orchestrating/Running"
            );
        }
        // A paused goal must not masquerade as a cancellation, and a blocked
        // goal must not masquerade as a hard failure.
        assert_ne!(group_status_for_goal("paused"), GroupStatus::Cancelled);
        assert_ne!(group_status_for_goal("blocked"), GroupStatus::Failed);
        // Unknown states fall back conservatively to a stopped, non-running
        // status.
        assert_eq!(group_status_for_goal("wat"), GroupStatus::Cancelled);
    }

    /// #25 — the operator reopen exit: a BLOCKED goal (no model-reachable
    /// way out, since `MODEL_ALLOWED_TRANSITIONS` only admits
    /// complete/blocked and the complete gate refuses a blocked goal) is
    /// reopened to `active` via [`Self::operator_transition_goal`], and can
    /// then be closed through the normal `goal_update` (model complete)
    /// path — the state machine has a full blocked → active → complete loop.
    #[tokio::test]
    async fn operator_reopen_unblocks_goal_then_model_completes() {
        let orchestrator = InProcessAgentOrchestrator::default();
        let session_id = SessionKey::with_profile("tenant-a", "api", "goal-25-reopen");
        seed_goal(&orchestrator, &session_id, "tenant-a");
        // The model blocks the goal (a model-allowed transition).
        orchestrator
            .model_transition_goal(&session_id, "tenant-a", "blocked", "stuck", None)
            .await
            .expect("block");
        // A blocked goal has no model exit: goal_update to complete is gated.
        // The OPERATOR reopens it.
        let reopened = orchestrator
            .operator_transition_goal(
                &session_id,
                "tenant-a",
                None,
                "reopen",
                "operator reopened",
                None,
            )
            .expect("operator reopen");
        assert_eq!(reopened["status"], json!("active"));
        // After reopen the model can close the goal via goal_update.
        orchestrator
            .model_transition_goal(&session_id, "tenant-a", "complete", "done", None)
            .await
            .expect("complete after reopen");
        let goal = orchestrator
            .get_goal(GoalSessionRequest {
                session_id: session_id.clone(),
                profile_id: "tenant-a".into(),
            })
            .expect("get goal");
        assert_eq!(goal["goal"]["status"], json!("complete"));
    }

    /// #25 — `archived` is a TERMINAL state: once archived, neither reopen
    /// nor any further operator/model transition can move the goal.
    #[test]
    fn operator_archive_is_terminal_and_irreversible() {
        let orchestrator = InProcessAgentOrchestrator::default();
        let session_id = SessionKey::with_profile("tenant-a", "api", "goal-25-archive");
        seed_goal(&orchestrator, &session_id, "tenant-a");
        let archived = orchestrator
            .operator_transition_goal(
                &session_id,
                "tenant-a",
                None,
                "archive",
                "operator archived",
                None,
            )
            .expect("archive");
        assert_eq!(archived["status"], json!("archived"));
        // Reopen from archived is refused.
        let reopen = orchestrator.operator_transition_goal(
            &session_id,
            "tenant-a",
            None,
            "reopen",
            "nope",
            None,
        );
        assert!(reopen.is_err());
        // A second archive is refused (idempotence guard).
        let again = orchestrator.operator_transition_goal(
            &session_id,
            "tenant-a",
            None,
            "archive",
            "again",
            None,
        );
        assert!(again.is_err());
    }

    #[test]
    fn goal_operator_archive_race_shutdown_drain_cannot_revive_live_snapshot() {
        let dir = tempfile::tempdir().unwrap();
        let orchestrator = InProcessAgentOrchestrator::default();
        orchestrator
            .configure_supervisor_store(dir.path().join("supervisor"))
            .unwrap();
        let session_id = SessionKey::with_profile("tenant-a", "api", "archive-race");
        let created = orchestrator
            .set_goal(GoalSetRequest {
                session_id: session_id.clone(),
                profile_id: "tenant-a".into(),
                objective: "race archive against a draining turn".into(),
                status: Some("active".into()),
                token_budget: Some(100_000),
                transition_actor: None,
            })
            .unwrap();
        let goal_id = created["goal"]["goal_id"].as_str().unwrap().to_owned();
        assert_eq!(orchestrator.pending_continuation_count_for_test(), 1);
        orchestrator
            .operator_transition_goal(
                &session_id,
                "tenant-a",
                Some(&goal_id),
                "archive",
                "operator won the race",
                Some(dir.path()),
            )
            .unwrap();
        assert_eq!(
            orchestrator.pending_continuation_count_for_test(),
            0,
            "archive must tombstone queued GoalContinue work"
        );

        // This is the same post-turn accountant used by stdio's bounded
        // shutdown drain. A turn dispatched before archive may arrive late,
        // but its persist must preserve the archived status.
        let _ = orchestrator.record_goal_turn(&session_id, "tenant-a", Some(&goal_id), 123, 1);
        let live = orchestrator
            .get_goal(GoalSessionRequest {
                session_id: session_id.clone(),
                profile_id: "tenant-a".into(),
            })
            .unwrap();
        assert_eq!(live["goal"]["status"], json!("archived"));
        let replay = SupervisorStore::new(dir.path().join("supervisor"))
            .load_goal_groups_by_id()
            .unwrap();
        let persisted = replay
            .values()
            .find(|group| {
                supervisor_metadata_str(&group.metadata, "goal_id") == Some(goal_id.as_str())
            })
            .unwrap();
        assert_eq!(
            supervisor_metadata_str(&persisted.metadata, "status"),
            Some("archived")
        );
        let ledger = octos_fleet::GoalLedger::open(InProcessAgentOrchestrator::goal_ledger_path(
            dir.path(),
            &goal_id,
        ))
        .unwrap();
        assert_eq!(
            ledger.get_goal(&goal_id).unwrap().unwrap().status,
            "archived"
        );
    }

